package com.example.alertbox; import android.content.DialogInterface; import android.os.Bundle; import android.view.View; import android.widget.Toast; import androidx.appcompat.app.AlertDialog; import androidx.appcompat.app.AppCompatActivity; public class MainActivity extends AppCompatActivity { @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);} public void showAlertDialog(View v){AlertDialog.Builder builder=new AlertDialog.Builder(this);builder.setTitle("Notification");builder.setMessage("This is an alert dialog box triggered by your button click!");builder.setCancelable(false);builder.setPositiveButton("OK",(d,w)->{Toast.makeText(this,"Clicked OK",Toast.LENGTH_SHORT).show();d.dismiss();});builder.setNegativeButton("Cancel",(d,w)->{Toast.makeText(this,"Dialog Cancelled",Toast.LENGTH_SHORT).show();d.dismiss();});builder.create().show();}}
